package fyne

import (
	"net/url"
	"sync"
)

// An App is the definition of a graphical application.
// Apps can have multiple windows, by default they will exit when all windows
// have been closed. This can be modified using SetMaster() or SetCloseIntercept().
// To start an application you need to call Run() somewhere in your main() function.
// Alternatively use the window.ShowAndRun() function for your main window.
type App interface {
	// Create a new window for the application.
	// The first window to open is considered the "master" and when closed
	// the application will exit.
	NewWindow(title string) Window

	// Open a URL in the default browser application.
	OpenURL(url *url.URL) error

	// Icon returns the application icon, this is used in various ways
	// depending on operating system.
	// This is also the default icon for new windows.
	Icon() Resource

	// SetIcon sets the icon resource used for this application instance.
	SetIcon(Resource)

	// Run the application - this starts the event loop and waits until Quit()
	// is called or the last window closes.
	// This should be called near the end of a main() function as it will block.
	Run()

	// Calling Quit on the application will cause the application to exit
	// cleanly, closing all open windows.
	// This function does no thing on a mobile device as the application lifecycle is
	// managed by the operating system.
	Quit()

	// Driver returns the driver that is rendering this application.
	// Typically not needed for day to day work, mostly internal functionality.
	Driver() Driver

	// UniqueID returns the application unique identifier, if set.
	// This must be set for use of the Preferences() functions... see NewWithId(string)
	UniqueID() string

	// SendNotification sends a system notification that will be displayed in the operating system's notification area.
	SendNotification(*Notification)

	// Settings return the globally set settings, determining theme and so on.
	Settings() Settings

	// Preferences returns the application preferences, used for storing configuration and state
	Preferences() Preferences

	// Storage returns a storage handler specific to this application.
	Storage() Storage

	// Lifecycle returns a type that allows apps to hook in to lifecycle events.
	Lifecycle() Lifecycle

	// Metadata returns the application's build-time metadata.
	//
	// Since: 2.5
	Metadata() AppMetadata
}

var app App
var appLock sync.RWMutex

// SetCurrentApp is an internal function to set the app instance currently running.
func SetCurrentApp(current App) {
	appLock.Lock()
	defer appLock.Unlock()

	app = current
}

// CurrentApp returns the current application, for which there is only 1 per process.
func CurrentApp() App {
	appLock.RLock()
	defer appLock.RUnlock()

	if app == nil {
		LogError("Attempt to access current Fyne app when none is started", nil)
	}
	return app
}

// AppMetadata captures application build-time metadata that can be queried at runtime.
//
// Since: 2.5
type AppMetadata struct {
	// ID is the unique application identifier (e.g. "com.example.myapp")
	ID string
	// Name is the human-friendly application name
	Name string
	// Version is the application semantic version string (e.g. "1.0.0")

package fyne

// Menu stores the information required for a standard menu.
// A menu can pop down from a MainMenu or could be a pop out menu.
type Menu struct {
	Label string
	Items []*MenuItem
}

// NewMenu creates a new menu given the specified label (to show in a MainMenu) and list of items to display.
func NewMenu(label string, items ...*MenuItem) *Menu {
	return &Menu{Label: label, Items: items}
}

// Refresh triggers a refresh of the menu to reflect any changes.
//
// Since: 2.5
func (m *Menu) Refresh() {
	// Refresh implementation handled by the driver
}

// MenuItem is a single item within any menu, it contains a display Label and Action function that is called when tapped.
type MenuItem struct {
	ChildMenu *Menu
	// Since: 2.1
	IsQuit      bool
	IsSeparator bool
	Label       string
	Action      func()
	// Since: 2.1
	Disabled bool
	// Since: 2.1
	Checked bool
	// Icon is an optional icon to display next to the menu item label.
	//
	// Since: 2.5
	Icon Resource
	// Shortcut is an optional keyboard shortcut for the menu item.
	//
	// Since: 2.5
	Shortcut Shortcut
}

// NewMenuItem creates a new menu item from the passed label and action parameters.
func NewMenuItem(label string, action func()) *MenuItem {
	return &MenuItem{Label: label, Action: action}
}

// NewMenuItemSeparator creates a menu item that is to be used as a separator.
func NewMenuItemSeparator() *MenuItem {
	return &MenuItem{IsSeparator: true, Action: func() {}}
}

// MainMenu defines the data required to show a menu bar (desktop) or other appropriate top level menu.
type MainMenu struct {
	Items []*Menu
}

// NewMainMenu creates a top level menu structure used by fyne.Window for displaying a menubar
// (or appropriate equivalent).
func NewMainMenu(items ...*Menu) *MainMenu {
	return &MainMenu{items}
}

// Refresh triggers a refresh of the main menu to reflect any changes.
//
// Since: 2.5
func (m *MainMenu) Refresh() {
	for _, menu := range m.Items {
		menu.Refresh()
	}
}

package desktop

import "fyne.io/fyne/v2"

// App represents a desktop application with access to desktop-specific features.
//
// Since: 2.5
type App interface {
	fyne.App

	// SetSystemTrayMenu sets the system tray menu for the application.
	// On systems that support it, this will create a system tray icon with the specified menu.
	// The menu parameter can be nil to remove the system tray icon.
	SetSystemTrayMenu(menu *fyne.Menu)

	// SetSystemTrayIcon sets the icon for the system tray.
	// On systems that support it, this will display the specified icon in the system tray.
	// The icon parameter can be nil to use the default application icon.
	//
	// Since: 2.5
	SetSystemTrayIcon(icon fyne.Resource)
}

