package theme

import (
	"encoding/json"
	"fmt"
	"image/color"
	"io"
	"strconv"
	"strings"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// FromJSON parses a JSON string and returns a Theme. On parse error, returns the default theme along with the error.
//
// Since: 2.5
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses JSON from a Reader and returns a Theme. On parse error, returns the default theme along with the error.
//
// Since: 2.5
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var raw map[string]interface{}
	if err := json.NewDecoder(r).Decode(&raw); err != nil {
		return DarkTheme(), err
	}

	theme := &jsonTheme{
		colors:      make(map[fyne.ThemeColorName]color.Color),
		colorsDark:  make(map[fyne.ThemeColorName]color.Color),
		colorsLight: make(map[fyne.ThemeColorName]color.Color),
		sizes:       make(map[fyne.ThemeSizeName]float32),
		fonts:       make(map[string]fyne.Resource),
		icons:       make(map[fyne.ThemeIconName]fyne.Resource),
	}

	// Parse generic colors
	if colors, ok := raw["Colors"].(map[string]interface{}); ok {
		for name, val := range colors {
			if hexStr, ok := val.(string); ok {
				if c, err := parseHexColor(hexStr); err == nil {
					theme.colors[fyne.ThemeColorName(name)] = c
				}
			}
		}
	}

package binding

import (
	"fmt"
	"sync"

	"fyne.io/fyne/v2/storage"
)

// StringFormat supports binding a formatted string from a variable number of input DataItem bindings.
//
// Since: 2.5
type StringFormat interface {
	String
	AddListener(DataListener)
	RemoveListener(DataListener)
}

// NewSprintf returns a new StringFormat binding that formats its output using the specified format string and data bindings.
// The format string follows the same rules as fmt.Sprintf. The binding listens to all input sources and updates when any changes.
//
// Since: 2.5
func NewSprintf(format string, bindings ...DataItem) StringFormat {
	s := &boundSprintf{
		format:   format,
		bindings: bindings,
	}

	// Listen to all input bindings
	listener := NewDataListener(func() {
		s.lock.Lock()
		defer s.lock.Unlock()
		s.trigger()
	})

	for _, b := range bindings {
		b.AddListener(listener)
	}

	return s
}

// StringToStringWithFormat creates a bidirectional binding that formats a string binding.
// If format is "%s", the original binding is returned directly for efficiency.
//
// Since: 2.5
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		return str
	}

